// dispatch/trust-store.mjs — the ONE door onto an agent CLI's folder-trust store
// (Phase 01 group B of plans/260906-1831-dispatch-visibility-v0).
//
// WHY THIS EXISTS. An agent CLI records which directories a human has vouched
// for. claude keeps that in `~/.claude.json` under
// `projects[<absolute path>].hasTrustDialogAccepted`, keyed by EXACT path, not by
// prefix. Every fgOS dispatch runs in a fresh worktree, which is therefore a path
// the CLI has never seen: it opens a folder-trust dialog and the dispatch stops
// before doing anything at all. Measured 2026-09-06, with zero worktree paths
// present among the operator's own 145 entries — interactive dispatch into a
// worktree had never once worked. Evidence:
// docs/architect/agent-coordination/verification/visibility-herdr/proofs/2026-09-06-p6/.
//
// WHY IT IS A SEPARATE MODULE. Writing into a file another tool owns is exactly
// the kind of thing that should happen in one place, with one set of rules, so
// that "did fgOS vouch for a directory nobody vouched for?" has a single answer
// a reader can check. Nothing else in fgOS may open that file.
//
// THE RULE IT ENFORCES (B1). Trust is DERIVED, never invented: an entry is only
// written for a path whose repo root is ALREADY trusted by the human. fgOS
// vouching for a checkout of a repo the operator already vouched for is a
// derivation; fgOS vouching for an arbitrary directory would be fabrication.
//
// WHAT IT DELIBERATELY DOES NOT CLAIM TO ENFORCE. That the caller only passes
// paths fgOS itself created this dispatch. This module cannot verify that — a
// worktree may legitimately live anywhere, including outside the repo root
// (measured: the probes used /var/tmp). It is the caller's obligation, stated
// here rather than dressed up as a check that does nothing.

import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { uniqueTmpTag } from '../../util/unique-tmp-tag.mjs';

/** Raised for every refusal and every failure. Carries a `code` so a caller can
 * branch on the reason without matching message text. */
export class TrustStoreError extends Error {
  constructor(code, message, details = {}) {
    super(message);
    this.name = 'TrustStoreError';
    this.code = code;
    Object.assign(this, details);
  }
}

/** Read and parse the store, refusing loudly rather than inventing an empty one.
 * A missing file and an unparseable file are DIFFERENT failures: the first means
 * the CLI was never set up here, the second means something is wrong that a
 * silent overwrite would destroy. */
function readStore(storePath) {
  let raw;
  try {
    raw = fs.readFileSync(storePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new TrustStoreError('missing-store', `trust store not found at "${storePath}".`, { storePath });
    }
    throw new TrustStoreError('unreadable-store', `trust store at "${storePath}" could not be read: ${err.message}.`, { storePath });
  }
  try {
    return JSON.parse(raw);
  } catch (err) {
    // Never fall back to `{}` here. That would turn a corrupt-or-mid-edit file
    // into an empty one on the next write, discarding every entry the operator
    // has.
    throw new TrustStoreError('unreadable-store', `trust store at "${storePath}" is not valid JSON: ${err.message}.`, { storePath });
  }
}

/** Write `body` to `tmp` and rename it over `target`, keeping the target's own
 * permission bits. The stores this module edits hold provider credentials or
 * trust decisions (a 0600 file stays 0600); a temp file created with the
 * process default would silently widen it to 0664 under a 002 umask. A target
 * that does not exist yet is created owner-only. */
function writeFileKeepingMode(tmp, target, body) {
  let mode = 0o600;
  try { mode = fs.statSync(target).mode & 0o777; } catch { /* new file: owner-only */ }
  fs.writeFileSync(tmp, body, { mode });
  fs.chmodSync(tmp, mode); // writeFileSync's mode is masked by umask; chmod is not
  fs.renameSync(tmp, target);
}

/** Write the store atomically: a temp file in the SAME directory (so the rename
 * cannot cross a filesystem boundary and degrade into a copy), then rename over
 * the target. A reader therefore sees either the whole old file or the whole new
 * one, never a half-written store. The temp file is removed on any failure so a
 * crash leaves no residue beside the operator's own config. */
function writeStoreAtomic(storePath, data) {
  const dir = path.dirname(storePath);
  const tmp = path.join(dir, `.${path.basename(storePath)}.fgos-${process.pid}-${Date.now()}.tmp`);
  try {
    writeFileKeepingMode(tmp, storePath, `${JSON.stringify(data, null, 2)}\n`);
  } catch (err) {
    try { fs.unlinkSync(tmp); } catch {}
    throw new TrustStoreError('write-failed', `trust store at "${storePath}" could not be written: ${err.message}.`, { storePath });
  }
}

/** The `projects` map, or a typed schema-drift refusal. The shape is another
 * tool's, so it can change under us; when it does we want a named failure at the
 * door rather than a write that quietly lands somewhere meaningless. */
function projectsOf(store, storePath) {
  const projects = store.projects;
  if (!projects || typeof projects !== 'object' || Array.isArray(projects)) {
    throw new TrustStoreError(
      'schema-drift',
      `trust store at "${storePath}" has no usable "projects" object -- the store's shape changed and this module must not guess.`,
      { storePath },
    );
  }
  return projects;
}

/**
 * Trust state for one path: `true`, `false`, or `null` when the path is absent.
 *
 * The three-way answer is deliberate. "Absent" and "explicitly not trusted" look
 * the same to a boolean and mean different things: the first is a directory the
 * human has never been asked about, the second is one they declined.
 */
export function readTrust(storePath, projectPath) {
  const store = readStore(storePath);
  const projects = projectsOf(store, storePath);
  const entry = projects[projectPath];
  if (entry === undefined) return null;
  return entry?.hasTrustDialogAccepted === true;
}

/** The shape of one `projects[<path>]` entry claude.json's own schema
 * expects -- exported so a caller that must write this file's shape from
 * outside `seedTrust` (worker-home.mjs's private, freshly-created
 * `.claude.json`, which has no existing repoRoot entry to derive B1 trust
 * from) uses the SAME shape rather than a second, independently-drifting
 * copy of it. Returns a fresh object every call: entries are never shared
 * references a caller could mutate into each other. */
export function trustedProjectEntry() {
  return {
    allowedTools: [],
    hasTrustDialogAccepted: true,
    mcpServers: {},
    enabledMcpjsonServers: [],
    disabledMcpjsonServers: [],
    history: [],
  };
}

/**
 * Roots a workspace's trust may be derived from: the repository root the run
 * was started for and, for a linked worktree, the main checkout that owns it
 * (the same repository, and the root codex itself asks about). Never invents
 * a root: each is only a candidate for the "already trusted" check.
 */
export function trustRoots(projectPath, repoRoot) {
  const roots = [repoRoot];
  try {
    const common = execFileSync('git', ['rev-parse', '--path-format=absolute', '--git-common-dir'], {
      cwd: projectPath, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'],
    }).trim();
    if (common && path.basename(common) === '.git') roots.push(path.dirname(common));
  } catch { /* not a checkout: only the declared root is a candidate */ }
  return [...new Set(roots)];
}

/**
 * Per-process approval of the MCP servers a project declares in its own `.mcp.json`, as extra
 * claude arguments. claude asks a person to approve each such server before it starts, which
 * stops an unattended worker at a dialog. The approval is derived, never invented: only where the
 * repo root is already trusted in the account store, only for the servers the file names, and
 * only for this one process (`--settings`), so no shared file is written. Returns `[]` when there
 * is nothing to approve or the root is not trusted.
 */
export function claudeMcpApprovalArgs({ cwd, repoRoot, storePath }) {
  let names;
  try {
    const declared = JSON.parse(fs.readFileSync(path.join(cwd, '.mcp.json'), 'utf8'))?.mcpServers;
    names = declared && typeof declared === 'object' ? Object.keys(declared) : [];
    // A linked worktree is trusted through the main checkout that owns it, as for folder trust.
    if (names.length === 0 || !trustRoots(path.resolve(cwd), repoRoot).some((root) => readTrust(storePath, root) === true)) return [];
  } catch {
    return [];
  }
  return ['--settings', JSON.stringify({ enabledMcpjsonServers: names })];
}

/**
 * Record trust for `projectPath`, derived from an already-trusted `repoRoot`.
 *
 * Refuses, without writing anything, when:
 * - `projectPath` is not absolute (`invalid-path`) — a relative key would name a
 *   different directory depending on who reads it;
 * - `repoRoot` is absent from the store or not trusted (`untrusted-root`) — this
 *   is B1, the rule the whole module exists for;
 * - the store is missing, unparseable, or shaped unexpectedly.
 *
 * Idempotent: seeding an already-seeded path rewrites nothing.
 */
export function seedTrust(storePath, { projectPath, repoRoot } = {}) {
  if (typeof projectPath !== 'string' || !path.isAbsolute(projectPath)) {
    throw new TrustStoreError('invalid-path', `trust seed refused: projectPath must be an absolute path, got "${projectPath}".`, { projectPath });
  }
  if (typeof repoRoot !== 'string' || !path.isAbsolute(repoRoot)) {
    throw new TrustStoreError('invalid-path', `trust seed refused: repoRoot must be an absolute path, got "${repoRoot}".`, { repoRoot });
  }

  const store = readStore(storePath);
  const projects = projectsOf(store, storePath);

  if (projects[repoRoot]?.hasTrustDialogAccepted !== true) {
    throw new TrustStoreError(
      'untrusted-root',
      `trust seed refused for "${projectPath}": its repo root "${repoRoot}" is not itself trusted, so there is nothing to derive trust from.`,
      { projectPath, repoRoot },
    );
  }

  if (projects[projectPath]?.hasTrustDialogAccepted === true) return false; // already seeded

  projects[projectPath] = trustedProjectEntry();
  writeStoreAtomic(storePath, store);
  return true;
}

/**
 * Remove one entry. Returns whether there was one to remove.
 *
 * This is the other half of B3, and it is not optional housekeeping: without it
 * the store grows one entry per dispatch forever. Removing an absent entry is a
 * `false` return, never an error, so a teardown path can run unconditionally.
 */
export function removeTrust(storePath, projectPath) {
  const store = readStore(storePath);
  const projects = projectsOf(store, storePath);
  if (projects[projectPath] === undefined) return false;
  delete projects[projectPath];
  writeStoreAtomic(storePath, store);
  return true;
}

// ---------------------------------------------------------------------------
// The same policy, a second format.
//
// codex asks the identical question at startup -- "do you trust the contents of
// this directory?" -- and blocks on it exactly the way claude does. herdr reports
// that as `agent_not_ready`: "blocked during startup and is not ready for
// prompts". Measured, and measured again after trying the cheaper ways out:
// neither `-c projects."<path>".trust_level=trusted` as an invocation override
// nor any of codex's `--dangerously-bypass-*` flags clears it. Only a persisted
// entry does.
//
// It lives here rather than in a module of its own because the POLICY is the
// same and must not drift: trust is only ever derived from a root that is
// already trusted, keyed by exact path, written atomically. Only the file format
// differs. Two files would be two chances for those rules to disagree.
//
// Where codex keeps that file is DECLARED by the executor, never guessed. A
// shell alias may point `CODEX_HOME` somewhere other than ~/.codex -- on this
// machine it does -- and a dispatch process cannot see a shell alias. Seeding
// the wrong file leaves the dialog exactly where it was, with nothing to show
// for it.

/** Read codex's config.toml far enough to answer one question: is this exact
 * path trusted? Deliberately not a TOML parser -- it looks for the one section
 * shape codex writes, and says `null` when it cannot tell. */
export function readCodexTrust(configPath, projectPath) {
  if (typeof projectPath !== 'string' || !path.isAbsolute(projectPath)) {
    throw new TrustStoreError('invalid-path', `readCodexTrust: projectPath must be absolute, got "${projectPath}".`);
  }
  let body;
  try {
    body = fs.readFileSync(configPath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return null;
    throw new TrustStoreError('unreadable-store', `could not read codex config at ${configPath}: ${err.message}`, { configPath });
  }
  const section = codexSectionPattern(projectPath);
  const match = body.match(section);
  if (!match) return null;
  return /trust_level\s*=\s*"trusted"/.test(match[0]);
}

/** The `[projects."<path>"]` block for one path, up to the next section header
 * or end of file. The path is embedded literally, so it is escaped for regex
 * rather than interpolated raw. */
function codexSectionPattern(projectPath) {
  const escaped = projectPath.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp(`\\[projects\\."${escaped}"\\][^\\[]*`, 'm');
}

/**
 * Trust one workspace for codex, deriving that trust from a root codex already
 * trusts -- the same B1 rule the JSON store enforces, for the same reason:
 * fgOS may propagate a trust decision a person already made, never invent one.
 *
 * Append-only and idempotent. An existing entry for the same path is left
 * exactly as it is rather than rewritten, so this can never downgrade a
 * decision or reformat a file somebody else maintains.
 */
export function seedCodexTrust(configPath, { projectPath, repoRoot, rootConfigPath } = {}) {
  if (typeof projectPath !== 'string' || !path.isAbsolute(projectPath)) {
    throw new TrustStoreError('invalid-path', `seedCodexTrust: projectPath must be absolute, got "${projectPath}".`);
  }
  if (typeof repoRoot !== 'string' || !path.isAbsolute(repoRoot)) {
    throw new TrustStoreError('invalid-path', `seedCodexTrust: repoRoot must be absolute, got "${repoRoot}".`);
  }
  // `rootConfigPath` is the account's own config, where a person made the trust
  // decision this derives from. `configPath` is where the entry is written; it
  // differs only for a confined worker, whose private CODEX_HOME starts without
  // any config.toml, so the entry is written (and the file created) there while
  // the root is still vouched for by the real account config.
  const rootStore = rootConfigPath ?? configPath;
  if (readCodexTrust(configPath, projectPath) === true) return false;
  if (readCodexTrust(rootStore, repoRoot) !== true) {
    throw new TrustStoreError(
      'untrusted-root',
      `codex trust seed refused for "${projectPath}": its repo root "${repoRoot}" is not itself trusted in ${rootStore}, so there is nothing to derive trust from.`,
      { projectPath, repoRoot, configPath: rootStore },
    );
  }
  let body;
  try {
    body = fs.readFileSync(configPath, 'utf8');
  } catch (err) {
    if (err.code !== 'ENOENT' || rootStore === configPath) {
      throw new TrustStoreError('unreadable-store', `could not read codex config at ${configPath}: ${err.message}`, { configPath });
    }
    body = '';
  }
  const entry = `\n[projects."${projectPath}"]\ntrust_level = "trusted"\n`;
  const tmp = `${configPath}.tmp-${uniqueTmpTag()}`;
  try {
    fs.mkdirSync(path.dirname(configPath), { recursive: true });
    writeFileKeepingMode(tmp, configPath, `${body.replace(/\n*$/, '\n')}${entry}`);
  } catch (err) {
    try { fs.rmSync(tmp, { force: true }); } catch { /* the temp file is not worth a second failure */ }
    throw new TrustStoreError('write-failed', `could not write codex config at ${configPath}: ${err.message}`, { configPath });
  }
  return true;
}

/** Drop one workspace's codex trust entry. Returns whether anything was there. */
export function removeCodexTrust(configPath, projectPath) {
  if (readCodexTrust(configPath, projectPath) === null) return false;
  let body;
  try {
    body = fs.readFileSync(configPath, 'utf8');
  } catch {
    return false;
  }
  const next = body.replace(codexSectionPattern(projectPath), '');
  const tmp = `${configPath}.tmp-${uniqueTmpTag()}`;
  try {
    writeFileKeepingMode(tmp, configPath, next);
  } catch (err) {
    try { fs.rmSync(tmp, { force: true }); } catch { /* nothing further to do */ }
    throw new TrustStoreError('write-failed', `could not write codex config at ${configPath}: ${err.message}`, { configPath });
  }
  return true;
}

// ---------------------------------------------------------------------------
// codex hook trust: the same policy, one level down.
//
// Folder trust does not cover hooks. codex records trust for each hook of a
// project's `.codex/hooks.json` as `[hooks.state."<abs hooks.json>:<event>:<group>:<handler>"]
// trusted_hash = "sha256:..."` and asks for review at startup while the stored hash differs from
// the hook's current one. A confined worker's private CODEX_HOME starts empty, so every round
// would stop at that review. The hash is sha256 of the key-sorted JSON of
// `{event_name, matcher?, hooks:[{type, command, timeout, async, statusMessage?}]}` (openai/codex
// codex-rs/hooks/src/engine/discovery.rs + config/src/fingerprint.rs). A wrong hash only brings
// the review back; codex never trusts on a mismatch.
//
// Same B1 rule as folder trust: seeded only where the project's root is already trusted by a
// person, and only for the hooks currently in the file -- the decision the person would make by
// pressing "trust".

const DEFAULT_HOOK_TIMEOUT_SEC = 600;

function sortedJson(value) {
  if (Array.isArray(value)) return value.map(sortedJson);
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.keys(value).sort().map((key) => [key, sortedJson(value[key])]));
  }
  return value;
}

/** The trust hash codex computes for one command hook. */
export function codexHookTrustHash(eventName, matcher, handler) {
  const hook = { type: 'command', command: handler.command, timeout: handler.timeout ?? DEFAULT_HOOK_TIMEOUT_SEC, async: handler.async === true };
  if (typeof handler.statusMessage === 'string') hook.statusMessage = handler.statusMessage;
  const identity = { event_name: eventName, hooks: [hook] };
  if (typeof matcher === 'string') identity.matcher = matcher;
  return `sha256:${createHash('sha256').update(JSON.stringify(sortedJson(identity))).digest('hex')}`;
}

/** Hook entries of a hooks.json as `{ key, hash }`, plus how many handlers could not be hashed
 * faithfully (other handler types, fields whose normalisation is not reproduced here). */
export function codexHookTrustEntries(hooksJsonPath) {
  let parsed;
  try {
    parsed = JSON.parse(fs.readFileSync(hooksJsonPath, 'utf8'));
  } catch (err) {
    if (err.code === 'ENOENT') return { entries: [], skipped: 0 };
    throw new TrustStoreError('unreadable-store', `could not read codex hooks at ${hooksJsonPath}: ${err.message}`, { hooksJsonPath });
  }
  const entries = [];
  let skipped = 0;
  for (const [event, groups] of Object.entries(parsed?.hooks ?? {})) {
    const eventName = event.replace(/([a-z0-9])([A-Z])/g, '$1_$2').toLowerCase();
    (Array.isArray(groups) ? groups : []).forEach((group, groupIndex) => {
      (Array.isArray(group?.hooks) ? group.hooks : []).forEach((handler, handlerIndex) => {
        const hashable = eventName !== 'session_end' && handler?.type === 'command' && typeof handler.command === 'string'
          && handler.additionalContextLimit === undefined && handler.commandWindows === undefined && handler.command_windows === undefined;
        if (!hashable) { skipped += 1; return; }
        entries.push({
          key: `${hooksJsonPath}:${eventName}:${groupIndex}:${handlerIndex}`,
          hash: codexHookTrustHash(eventName, group.matcher, handler),
        });
      });
    });
  }
  return { entries, skipped };
}

/** A TOML basic-string key. JSON string escapes (quote, backslash, control characters) are valid
 * TOML escapes; DEL is the one extra character TOML requires escaped. */
function codexHookHeader(key) {
  return `[hooks.state.${JSON.stringify(key).replace(/\x7f/g, '\\u007f')}]`;
}

/**
 * Trust the project's codex hooks in `configPath`, which must be a worker's PRIVATE config: it is
 * created by fgOS and deleted with the home, so nothing here is ever removed again and the
 * operator's own config is never edited. Idempotent: a key already present (at any indentation)
 * is left as it is. Returns `{ keys, skipped }`.
 */
export function seedCodexHookTrust(configPath, { projectPath, repoRoot, rootConfigPath } = {}) {
  if (typeof projectPath !== 'string' || !path.isAbsolute(projectPath)) {
    throw new TrustStoreError('invalid-path', `seedCodexHookTrust: projectPath must be absolute, got "${projectPath}".`);
  }
  const { entries, skipped } = codexHookTrustEntries(path.join(projectPath, '.codex', 'hooks.json'));
  if (entries.length === 0) return { keys: [], skipped };
  const rootStore = rootConfigPath ?? configPath;
  if (readCodexTrust(rootStore, repoRoot) !== true) {
    throw new TrustStoreError(
      'untrusted-root',
      `codex hook trust seed refused for "${projectPath}": its repo root "${repoRoot}" is not itself trusted in ${rootStore}.`,
      { projectPath, repoRoot, configPath: rootStore },
    );
  }
  let body = '';
  try {
    body = fs.readFileSync(configPath, 'utf8');
  } catch (err) {
    if (err.code !== 'ENOENT') throw new TrustStoreError('unreadable-store', `could not read codex config at ${configPath}: ${err.message}`, { configPath });
  }
  // A key already present in any TOML form (standard table, dotted, single-quoted) is left alone:
  // appending a second table would make codex refuse the whole config.
  const fresh = entries.filter(({ key }) => !body.includes(codexHookHeader(key)) && !body.includes(key));
  if (fresh.length === 0) return { keys: [], skipped };
  const sections = fresh.map(({ key, hash }) => `\n${codexHookHeader(key)}\ntrusted_hash = "${hash}"\n`).join('');
  const tmp = `${configPath}.tmp-${uniqueTmpTag()}`;
  try {
    fs.mkdirSync(path.dirname(configPath), { recursive: true });
    writeFileKeepingMode(tmp, configPath, `${body.replace(/\n*$/, '\n')}${sections}`);
  } catch (err) {
    try { fs.rmSync(tmp, { force: true }); } catch { /* the temp file is not worth a second failure */ }
    throw new TrustStoreError('write-failed', `could not write codex config at ${configPath}: ${err.message}`, { configPath });
  }
  return { keys: fresh.map(({ key }) => key), skipped };
}

// ---------------------------------------------------------------------------
// The same policy, a third format: agy (Antigravity CLI).
//
// agy records trusted workspaces in `~/.gemini/antigravity-cli/settings.json`
// (or under the directory pointed to by $HOME) in a `trustedWorkspaces` string
// array of absolute paths. When agy launches in an untrusted directory (e.g. a
// fresh worktree), it shows a blocking folder-trust dialog that causes herdr
// to report `agent_not_ready`.
//
// Same B1 rule as the other two formats: trust is derived from a repoRoot
// already trusted, never invented, and a store this module cannot make sense
// of is refused rather than quietly treated as empty -- the same "unreadable
// beats fabricated" choice `readStore` makes for the JSON store above.

/** Where agy keeps its trust store under a given HOME. `homeDir` must be the
 * HOME the agy PROCESS itself will run under, never the operator's own --
 * an agy executor is declared with its own private HOME (typically
 * `~/.agy-homes/<name>`, resolved from the executor's own env), and seeding
 * `~/.gemini/...` under the wrong HOME leaves agy's own dialog exactly where
 * it was. */
export function defaultAgySettingsPath(homeDir = os.homedir()) {
  return path.join(homeDir, '.gemini', 'antigravity-cli', 'settings.json');
}

function matchesPath(entry, target) {
  if (typeof entry !== 'string' || typeof target !== 'string') return false;
  if (entry === target) return true;
  const entryNorm = path.normalize(entry);
  const targetNorm = path.normalize(target);
  if (entryNorm === targetNorm) return true;
  const entryResolved = path.resolve(entry);
  const targetResolved = path.resolve(target);
  if (entryResolved === targetResolved) return true;
  if (process.platform === 'win32') {
    if (entryNorm.toLowerCase() === targetNorm.toLowerCase()) return true;
    if (entryResolved.toLowerCase() === targetResolved.toLowerCase()) return true;
  }
  return false;
}

/** Read agy's settings.json to check whether a path is trusted. */
export function readAgyTrust(settingsPath, projectPath) {
  try {
    if (typeof settingsPath !== 'string' || typeof projectPath !== 'string') return null;
    if (!fs.existsSync(settingsPath)) return null;
    const raw = fs.readFileSync(settingsPath, 'utf8');
    const store = JSON.parse(raw);
    if (!Array.isArray(store?.trustedWorkspaces)) return null;
    return store.trustedWorkspaces.some((entry) => matchesPath(entry, projectPath));
  } catch {
    return null;
  }
}

/** Read agy's settings.json, refusing (never inventing `{}`) when the file
 * exists but cannot be understood. A missing file is a different case: agy
 * was simply never seeded here, so an empty `trustedWorkspaces` is correct,
 * not a fabrication. */
export function readAgyStore(settingsPath) {
  if (!fs.existsSync(settingsPath)) return {};
  let raw;
  try {
    raw = fs.readFileSync(settingsPath, 'utf8');
  } catch (err) {
    throw new TrustStoreError('unreadable-store', `agy trust store at "${settingsPath}" could not be read: ${err.message}.`, { settingsPath });
  }
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    throw new TrustStoreError('unreadable-store', `agy trust store at "${settingsPath}" is not valid JSON: ${err.message}.`, { settingsPath });
  }
  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new TrustStoreError('schema-drift', `agy trust store at "${settingsPath}" is not a JSON object -- its shape changed and this module must not guess.`, { settingsPath });
  }
  return parsed;
}

/**
 * Trust one workspace for agy, deriving that trust from a root agy already
 * trusts -- the same B1 rule the other two formats enforce, for the same
 * reason: fgOS may propagate a trust decision a person already made, never
 * invent one for a root nobody vouched for.
 *
 * Refuses, without writing anything, when:
 * - `projectPath`/`repoRoot` is not absolute (`invalid-path`);
 * - `repoRoot` is not itself in `trustedWorkspaces` (`untrusted-root`) --
 *   this includes a settings.json that does not exist yet, since nothing is
 *   trusted there at all;
 * - the store exists but is unreadable or shaped unexpectedly.
 *
 * Idempotent: seeding an already-seeded path rewrites nothing.
 */
export function seedAgyTrust(settingsPath, { projectPath, repoRoot, rootSettingsPath } = {}) {
  if (typeof settingsPath !== 'string' || !settingsPath.trim()) {
    throw new TrustStoreError('invalid-path', `agy trust seed refused: settingsPath must be a non-empty string, got "${settingsPath}".`);
  }
  if (typeof projectPath !== 'string' || !path.isAbsolute(projectPath)) {
    throw new TrustStoreError('invalid-path', `agy trust seed refused: projectPath must be an absolute path, got "${projectPath}".`, { projectPath });
  }
  if (typeof repoRoot !== 'string' || !path.isAbsolute(repoRoot)) {
    throw new TrustStoreError('invalid-path', `agy trust seed refused: repoRoot must be an absolute path, got "${repoRoot}".`, { repoRoot });
  }

  const store = readAgyStore(settingsPath);
  const trustedList = Array.isArray(store.trustedWorkspaces) ? store.trustedWorkspaces : [];

  // `rootSettingsPath`: the account's own settings, where a person trusted the
  // root. It differs from `settingsPath` only for a confined worker's private HOME.
  const rootStore = rootSettingsPath ?? settingsPath;
  const rootData = rootStore === settingsPath ? store : readAgyStore(rootStore);
  const rootList = Array.isArray(rootData.trustedWorkspaces) ? rootData.trustedWorkspaces : [];
  if (!rootList.some((entry) => matchesPath(entry, repoRoot))) {
    throw new TrustStoreError(
      'untrusted-root',
      `agy trust seed refused for "${projectPath}": its repo root "${repoRoot}" is not itself trusted in ${rootStore}, so there is nothing to derive trust from.`,
      { projectPath, repoRoot, settingsPath: rootStore },
    );
  }

  if (trustedList.some((entry) => matchesPath(entry, projectPath))) return false; // already seeded

  store.trustedWorkspaces = [...trustedList, projectPath];

  const dir = path.dirname(settingsPath);
  fs.mkdirSync(dir, { recursive: true });
  const tmp = path.join(dir, `.${path.basename(settingsPath)}.fgos-${process.pid}-${Date.now().toString(36)}.tmp`);
  try {
    writeFileKeepingMode(tmp, settingsPath, `${JSON.stringify(store, null, 2)}\n`);
  } catch (err) {
    try { fs.unlinkSync(tmp); } catch {}
    throw new TrustStoreError('write-failed', `agy trust store at "${settingsPath}" could not be written: ${err.message}.`, { settingsPath });
  }
  return true;
}

/** Drop one workspace's agy trust entry. Returns whether anything was there. */
export function removeAgyTrust(settingsPath, projectPath) {
  try {
    if (typeof settingsPath !== 'string' || typeof projectPath !== 'string') return false;
    if (!fs.existsSync(settingsPath)) return false;
    const raw = fs.readFileSync(settingsPath, 'utf8');
    const store = JSON.parse(raw);
    if (!Array.isArray(store?.trustedWorkspaces)) return false;
    const idx = store.trustedWorkspaces.findIndex((entry) => matchesPath(entry, projectPath));
    if (idx === -1) return false;
    store.trustedWorkspaces.splice(idx, 1);
    const dir = path.dirname(settingsPath);
    const tmp = path.join(dir, `.${path.basename(settingsPath)}.fgos-${process.pid}-${Date.now().toString(36)}.tmp`);
    try {
      writeFileKeepingMode(tmp, settingsPath, `${JSON.stringify(store, null, 2)}\n`);
    } catch {
      try { fs.unlinkSync(tmp); } catch {}
      return false;
    }
    return true;
  } catch {
    return false;
  }
}

// dispatch/worker-home.mjs — build and tear down the private HOME a dispatched
// worker runs under (Phase 01 group C1 of plans/260906-1831-dispatch-visibility-v0).
//
// WHY A PRIVATE HOME AT ALL. Two problems settle with one mechanism. It closes
// the `$HOME/.config/herdr/herdr.sock` path a worker would otherwise use to reach
// the operator's own terminal cockpit (measured 2026-09-06: with a private HOME
// that route is blocked, without one it is open), and it is the writable private
// scratch that P00.1's Known Limitation already required before an agent CLI can
// start under a read-only mount at all.
//
// WHY IT MUST BE PROVISIONED, NOT MERELY EMPTY. An empty HOME is not a private
// HOME, it is a broken one. The five items below were not designed up front; each
// was found by hitting its own failure while running a real agent:
//
//   1. `.zshrc`                              -- without it zsh runs its first-run
//      wizard, which sits where the shell prompt should be. herdr types the launch
//      command into it, the wizard consumes the first keystroke as a menu choice,
//      and `claude --model haiku` arrives at the shell as `laude --model haiku`.
//   2. `.claude/.credentials.json`           -- provider auth.
//   3. `.claude.json` onboarding + theme     -- without it the agent starts but sits
//      in its own onboarding wizard, unable to accept an instruction, WHILE herdr
//      reports it `idle` and `interactive_ready`. A prompt sent then is swallowed.
//   4. `.claude.json` workspace trust        -- without it the folder-trust dialog.
//   5. `.claude/settings.json`
//      `skipDangerousModePermissionPrompt`   -- only when the declared posture is
//      `bypass`. That flag triggers a one-time acceptance screen which herdr
//      correctly classifies as `blocked`, so declaring bypass without this leaves a
//      dispatch that fails safely at startup and is useless.
//
// Evidence for every line above:
// docs/architect/agent-coordination/verification/visibility-herdr/proofs/2026-09-06-isolation/
//
// WHAT THIS DOES NOT SOLVE, stated so nobody assumes otherwise. The worker ends up
// holding a copy of the operator's provider credential, because the credential has
// to be reachable for the worker to function at all. HOME isolation cannot fix
// that; only a credential-holding relay can, and that is named as open in
// docs/architect/proposals/coordination-worker-provider-boundary.md.

import fs from 'node:fs';
import path from 'node:path';
import { readTrust, trustedProjectEntry, TrustStoreError } from './trust-store.mjs';
import { stopProcessesInside } from './stop-processes-inside.mjs';

/** Marker file written into every home this module creates. `removeWorkerHome`
 * refuses to delete a directory that does not carry it, so a teardown bug can
 * never turn into "recursively delete some path someone passed in". */
const MARKER = '.fgos-worker-home';

export class WorkerHomeError extends Error {
  constructor(code, message, details = {}) {
    super(message);
    this.name = 'WorkerHomeError';
    this.code = code;
    Object.assign(this, details);
  }
}

/**
 * Create a provisioned private HOME for one Run.
 *
 * `permissionMode` is `'ask'` or `'bypass'` and is DECLARED by the caller from the
 * executor profile — never inherited from a shell alias. That distinction is the
 * whole point of C4: on a developer machine the bypass flag reaches the agent
 * through `~/.zshrc`, which fgOS cannot see and a private HOME silently removes.
 *
 * Refuses, leaving nothing behind, when the repo root is not already trusted
 * (`untrusted-root`, the same B1 rule as `trust-store.mjs` and deliberately the
 * same implementation) or the source home has no credential to copy
 * (`missing-credential`).
 *
 * Returns `{ homePath, provisioned }` where `provisioned` names the items written,
 * so a caller can log what a Run actually got rather than what it assumed.
 */
export function createWorkerHome(baseDir, { runId, sourceHome, workspacePath, repoRoot, permissionMode = 'ask' } = {}) {
  if (typeof runId !== 'string' || runId.length === 0) {
    throw new WorkerHomeError('invalid-arg', 'createWorkerHome: runId is required.');
  }
  if (typeof workspacePath !== 'string' || !path.isAbsolute(workspacePath)) {
    throw new WorkerHomeError('invalid-arg', `createWorkerHome: workspacePath must be absolute, got "${workspacePath}".`);
  }
  if (permissionMode !== 'ask' && permissionMode !== 'bypass') {
    throw new WorkerHomeError('invalid-arg', `createWorkerHome: permissionMode must be "ask" or "bypass", got "${permissionMode}".`);
  }

  // B1 runs BEFORE anything is created, so a refusal leaves no directory behind.
  // Reusing trust-store's reader keeps "is this root trusted" in one place; a
  // second copy of that rule is how the two drift apart.
  const sourceStore = path.join(sourceHome, '.claude.json');
  let rootTrust;
  try {
    rootTrust = readTrust(sourceStore, repoRoot);
  } catch (err) {
    if (err instanceof TrustStoreError) {
      throw new WorkerHomeError(err.code, `createWorkerHome: could not read the source trust store: ${err.message}`, { sourceStore });
    }
    throw err;
  }
  if (rootTrust !== true) {
    throw new WorkerHomeError(
      'untrusted-root',
      `createWorkerHome refused: repo root "${repoRoot}" is not trusted in the source home, so a worker home for "${workspacePath}" would be inventing trust rather than deriving it.`,
      { repoRoot, workspacePath },
    );
  }

  const credentialSource = path.join(sourceHome, '.claude', '.credentials.json');
  if (!fs.existsSync(credentialSource)) {
    throw new WorkerHomeError(
      'missing-credential',
      `createWorkerHome refused: no provider credential at "${credentialSource}". A worker home without auth cannot do any work, and starting one anyway only fails later and less clearly.`,
      { credentialSource },
    );
  }

  const homePath = fs.mkdtempSync(path.join(baseDir, `worker-${runId}-`));
  const claudeDir = path.join(homePath, '.claude');
  const provisioned = [];
  try {
    fs.mkdirSync(claudeDir, { recursive: true });
    fs.writeFileSync(path.join(homePath, MARKER), `${runId}\n`);

    fs.writeFileSync(path.join(homePath, '.zshrc'), '# provisioned by fgOS: present so zsh does not run its first-run wizard\n');
    provisioned.push('.zshrc');

    // Copy, never link: a symlink would leave the worker a path back into the
    // operator's home. `COPYFILE_EXCL` keeps this from ever overwriting.
    fs.copyFileSync(credentialSource, path.join(claudeDir, '.credentials.json'), fs.constants.COPYFILE_EXCL);
    fs.chmodSync(path.join(claudeDir, '.credentials.json'), 0o600);
    provisioned.push('.claude/.credentials.json');

    fs.writeFileSync(path.join(homePath, '.claude.json'), `${JSON.stringify({
      hasCompletedOnboarding: true,
      theme: 'dark',
      installMethod: 'native',
      projects: {
        // Same shape trust-store.mjs's own `seedTrust` writes for the
        // operator's store -- one definition of what a trusted entry looks
        // like, so the two writers of this file format cannot drift apart.
        [workspacePath]: trustedProjectEntry(),
      },
    }, null, 2)}\n`);
    provisioned.push('.claude.json (onboarding + workspace trust)');

    if (permissionMode === 'bypass') {
      fs.writeFileSync(path.join(claudeDir, 'settings.json'), `${JSON.stringify({
        skipDangerousModePermissionPrompt: true,
      }, null, 2)}\n`);
      provisioned.push('.claude/settings.json (bypass acceptance)');
    }
  } catch (err) {
    // Never leave a half-provisioned home: a home missing one of the five fails
    // in a way that looks like an agent problem rather than a setup problem.
    try { fs.rmSync(homePath, { recursive: true, force: true }); } catch {}
    throw new WorkerHomeError('provision-failed', `createWorkerHome could not provision "${homePath}": ${err.message}`, { homePath });
  }

  return { homePath, provisioned };
}

/**
 * Remove a home this module created. Returns whether there was one.
 *
 * Refuses any directory without the marker file. Teardown runs on error paths,
 * where a wrong argument is most likely, and a recursive delete is the one
 * operation that must never act on a path it cannot recognise.
 */
export function removeWorkerHome(homePath) {
  if (typeof homePath !== 'string' || homePath.length === 0) {
    throw new WorkerHomeError('invalid-arg', 'removeWorkerHome: homePath is required.');
  }
  if (!fs.existsSync(homePath)) return false;
  if (!fs.existsSync(path.join(homePath, MARKER))) {
    throw new WorkerHomeError(
      'not-a-worker-home',
      `removeWorkerHome refused: "${homePath}" carries no ${MARKER} marker, so this module did not create it and will not delete it.`,
      { homePath },
    );
  }
  // A home is private to one dispatch: whatever still runs from it (an agent CLI's own background
  // server) is a leftover of that dispatch and would outlive the files it runs from.
  stopProcessesInside(homePath);
  fs.rmSync(homePath, { recursive: true, force: true });
  return true;
}

/**
 * Take the provider credential out of a home that is being kept.
 *
 * A failed round keeps its home for the same reason it keeps its pane: the
 * settings and rc are the only record of what the worker was actually given.
 * The credential is not part of that record. It is a plain copy of the
 * operator's own, and one copy per failed round accumulating in a world-
 * listable temp directory is a different thing from "the worker holds a copy
 * while it runs".
 *
 * Same marker check as `removeWorkerHome`, for the same reason: this runs on
 * error paths, where a wrong argument is most likely.
 */
export function redactWorkerHome(homePath) {
  if (typeof homePath !== 'string' || homePath.length === 0) {
    throw new WorkerHomeError('invalid-arg', 'redactWorkerHome: homePath is required.');
  }
  if (!fs.existsSync(homePath)) return false;
  if (!fs.existsSync(path.join(homePath, MARKER))) {
    throw new WorkerHomeError(
      'not-a-worker-home',
      `redactWorkerHome refused: "${homePath}" carries no ${MARKER} marker, so this module did not create it and will not touch it.`,
      { homePath },
    );
  }
  const credential = path.join(homePath, '.claude', '.credentials.json');
  if (!fs.existsSync(credential)) return false;
  fs.rmSync(credential, { force: true });
  return true;
}

// frozen-judge.mjs — fgOS's post-execution frozen-judge equivalent (STR63).
//
// bee's own frozen-judge (.bee/bin/lib/cells.mjs, decision 0018) flags a
// worker that rewrote the test suite, CI config, lockfiles, or manifests
// WITHOUT declaring those files in its own scope. fgOS already had both
// ingredients bee's check needs — an item's declared `footprint` and its
// actual changed files — but nothing composed them (docs/history/
// str63-frozen-judge-fgos/CONTEXT.md D1). This module is that composition:
// advisory only, never blocks anything (STR63 cos: "advisory, không tự
// fail, giống tinh thần frozen-judge").
//
// Pattern list ported from bee's FROZEN_JUDGE_PATTERNS (CONTEXT.md D2 chose
// verbatim-port for the smallest scope); the ".bee/config.json"-specific
// entry is dropped (fgOS has no .bee/), a ".fgos/"-specific entry is a
// noted follow-up, not in scope here.
import { normalizePath } from '../util/normalize-path.mjs';

export const FROZEN_JUDGE_PATTERNS = [
  { rule: 'test sources', pattern: /(^|\/)(tests?|__tests__|specs?)\// },
  { rule: 'test file', pattern: /\.(test|spec)\.[a-z]+$/i },
  { rule: 'snapshot', pattern: /(^|\/)__snapshots__\/|\.snap$/i },
  {
    rule: 'CI config',
    pattern: /(^|\/)\.github\/workflows\/|(^|\/)\.gitlab-ci\.yml$|(^|\/)Jenkinsfile$|(^|\/)azure-pipelines\.yml$|(^|\/)\.circleci\//i,
  },
  {
    rule: 'lockfile',
    pattern:
      /(^|\/)(package-lock\.json|yarn\.lock|pnpm-lock\.yaml|bun\.lockb?|Cargo\.lock|poetry\.lock|uv\.lock|go\.sum|composer\.lock|Gemfile\.lock)$/i,
  },
  {
    rule: 'package manifest',
    pattern: /(^|\/)(package\.json|pyproject\.toml|Cargo\.toml|go\.mod|composer\.json|Gemfile)$/i,
  },
  {
    rule: 'test config',
    pattern: /(^|\/)(jest\.config|vitest\.config|playwright\.config|karma\.conf|pytest\.ini|tox\.ini|phpunit\.xml)[^/]*$/i,
  },
];

/**
 * Frozen-judge check: judge-pattern files changed outside the item's
 * declared `footprint`. Footprint entries match by EXACT path only — the
 * same semantics footprintOverlap already uses (graph-metrics.mjs, plain
 * Set membership), no directory-prefix or glob support: `footprint` has
 * never carried either convention in fgOS.
 *
 * @param {string[]} changedFiles - actual files changed by this return/approve
 * @param {string[]} footprint - the item's declared footprint (may be absent)
 * @returns {{file:string, rule:string}[]} hits — empty means the judge is intact.
 */
export function frozenJudgeHits(changedFiles, footprint = []) {
  const declared = new Set((Array.isArray(footprint) ? footprint : []).map(normalizePath));
  const hits = [];
  for (const raw of Array.isArray(changedFiles) ? changedFiles : []) {
    const file = normalizePath(raw);
    if (!file) continue;
    const match = FROZEN_JUDGE_PATTERNS.find(({ pattern }) => pattern.test(file));
    if (!match) continue;
    if (declared.has(file)) continue;
    hits.push({ file, rule: match.rule });
  }
  return hits;
}

/**
 * Footprint-diff advisory (tsk-2ig, D3/D5 of docs/history/parallel-
 * decomposition-footprint-avoidance/CONTEXT.md — mức 1, advisory-only):
 * broadened sibling of `frozenJudgeHits` that flags ANY changed file
 * outside the item's declared `footprint`, not just the
 * `FROZEN_JUDGE_PATTERNS` subset — this is a SEPARATE function, never a
 * modification of `frozenJudgeHits` (D5: the existing narrow check's
 * behavior stays byte-for-byte unchanged).
 *
 * D5's exemption: an item with NO declared footprint (absent or empty
 * array) is exempt entirely — returns `[]` regardless of the diff.
 * Flagging every file in that case would be 100% of the diff, which is
 * not a signal (no declared baseline to diverge FROM), only guaranteed
 * noise — the opposite of `frozenJudgeHits`'s own fallback (which, for
 * the narrower judge-pattern set only, treats an absent footprint as
 * "check everything" since that subset is rare enough in a typical diff
 * to stay a real signal there).
 *
 * @param {string[]} changedFiles - actual files changed by this return/approve
 * @param {string[]} footprint - the item's declared footprint (may be absent)
 * @returns {{file:string}[]} hits — empty means every changed file is
 *   inside the declared footprint (or footprint was never declared, D5).
 */
export function footprintDiffHits(changedFiles, footprint = []) {
  const declaredList = Array.isArray(footprint) ? footprint : [];
  if (declaredList.length === 0) return []; // D5: absent footprint = exempt
  const declared = new Set(declaredList.map(normalizePath));
  const hits = [];
  for (const raw of Array.isArray(changedFiles) ? changedFiles : []) {
    const file = normalizePath(raw);
    if (!file) continue;
    if (declared.has(file)) continue;
    hits.push({ file });
  }
  return hits;
}

// goal-check.mjs — the goal-check primitive (per D3): run the item's own
// `verify` — the literal command string, via a shell, in the given cwd —
// and judge only by its exit status. The caller's own report (worker
// process, or a human returning an item) is never trusted on its own.
//
// Extracted from loop.mjs (stage-decompose S2-pull, cell action (3)): the
// runner calls this inside a worktree, `bin/fgos.mjs`'s `return` verb calls
// the exact same function directly in the host repo's cwd — one goal-check
// implementation, never two.

import { spawn } from 'node:child_process';
import { runBorrowed } from '../holder-lock/index.mjs';

// ASYNC CONVERSION (D16 wiring surface, fan-out-parallel): converted from
// spawnSync to the event-based `spawn` API. The defined timeout contract is
// unchanged and load-bearing — a timeout RESOLVES (never rejects/throws)
// `{passed:false, status:null, ...}`, exactly what spawnSync's own
// timeout->status:null behavior already gave every caller (runOnce's
// startupReap/processItem, merge.mjs's mergeRunnerItem, bin/fgos.mjs's
// return/approve verbs) — none of them expect runGoalCheck to ever reject.
//
// tsk-53o: a timeout and a genuine verify FAILURE were both indistinguishable
// statusless outcomes (`{passed:false, status:null}`) — the same shape a
// spawn failure (the shell itself missing) already produced too. A caller
// under real load (~15 parallel sessions sharing one machine) could not tell
// "this item is actually broken" from "the check itself ran out of time" and
// parked the item `blocked` on a false negative, quoting a misleading
// `(exit null)`. `timedOut` is now always present on the resolved object
// (`true` on the timeout branch below, `false` on every other branch,
// including the spawn-failure branch) — additive only, load-bearing exactly
// like the rest of this contract: `passed`/`status`/`output` keep their
// existing meaning unchanged, and every caller must now read `timedOut`
// before treating a `!passed` result as proof the item's own verify failed.
// tsk-516: the same spawn/timeout/capture contract, addressed by a literal
// command string instead of an item. `runGoalCheck` below is now a thin
// wrapper over this, so the item's own verify and the repo-invariant checks
// (docs/history/tsk-516-approve-reverify-scope/CONTEXT.md D3) share ONE
// implementation of the timeout semantics tsk-53o pinned -- a second copy
// would be a second place for `timedOut` to drift.
//
// `custody` (optional): an acquired lock handle the caller holds over `cwd`.
// The shell then runs as a borrower of that handle (runBorrowed), so the
// command and everything it spawns keep the lease while they run, and the
// result settles only after the borrow's leftover sweep. A sweep that cannot
// prove the lease alone again rejects: that is an authority failure, not a
// verify verdict.
export function runCommand(command, cwd, timeoutMs, { custody } = {}) {
  const maxBuffer = 10 * 1024 * 1024;
  return new Promise((resolve, reject) => {
    // `stdin: 'ignore'` (never the 'pipe' default): a verify command that
    // checks for piped stdin (codex's own "Reading additional input from
    // stdin..." probe, tsk-3tkc) blocks forever on an open-but-unwritten
    // pipe here, since nothing in this runner ever writes to or closes
    // child.stdin -- same fix as src/runner/dispatch/transport.mjs's
    // cliSpawnAdapter.
    const child = custody
      ? runBorrowed(custody, { command: shellCommand(), args: shellArgs(command), cwd, detached: true, stdin: 'ignore', maxOutputBytes: maxBuffer }, { sync: false })
      : spawn(command, { shell: true, cwd, stdio: ['ignore', 'pipe', 'pipe'] });
    child.stdout.setEncoding('utf8');
    child.stderr.setEncoding('utf8');

    let stdout = '';
    let stderr = '';
    let stdoutLen = 0;
    let stderrLen = 0;
    let settled = false;
    let timedOut = false;
    let timer = null;

    const finish = (fn) => {
      if (settled) return;
      settled = true;
      if (timer) clearTimeout(timer);
      fn();
    };

    if (timeoutMs) {
      timer = setTimeout(() => {
        timedOut = true;
        child.kill('SIGTERM');
      }, timeoutMs);
    }

    child.stdout.on('data', (chunk) => {
      stdoutLen += Buffer.byteLength(chunk);
      if (stdoutLen + stderrLen <= maxBuffer) stdout += chunk;
    });
    child.stderr.on('data', (chunk) => {
      stderrLen += Buffer.byteLength(chunk);
      if (stdoutLen + stderrLen <= maxBuffer) stderr += chunk;
    });

    // A genuine spawn failure (e.g. the shell itself missing) is not a
    // defined outcome spawnSync ever surfaced through a distinct branch here
    // either — it fell straight through to `status: null` the same way a
    // timeout does (spawnSync sets status:null on any failure-to-run). Mirror
    // that: never reject, resolve as a failed, statusless check.
    child.on('error', () => {
      finish(() => {
        resolve({ passed: false, status: null, timedOut: false, output: `${stdout}${stderr}` });
      });
    });

    // 'exit' (fires once the spawned process itself terminates), never
    // 'close' (waits for the stdio PIPES to fully close too): `verify` runs
    // via a shell (shell:true), and a shell running a single command often
    // FORKS rather than execs into it (observed with dash) — the shell
    // process can die from the timeout's SIGTERM in milliseconds while a
    // grandchild it spawned keeps the stdout/stderr pipe open for however
    // long IT keeps running. Resolving on 'close' would make a killed
    // timeout silently wait out the grandchild's full runtime — the same
    // grandchild caveat dispatch.mjs already documents for spawnWorker,
    // applying here to shell:true instead of a spawned executor tree.
    // spawnSync's own timeout returns as soon as the direct child (the
    // shell) is confirmed dead, never waiting on any grandchild — 'exit'
    // reproduces that same timing exactly.
    child.on('exit', (code) => {
      const settle = () => finish(() => {
        resolve({
          passed: !timedOut && code === 0,
          status: timedOut ? null : code,
          timedOut,
          output: `${stdout}${stderr}`,
        });
      });
      if (!child.borrowed) return settle();
      // A borrowed shell settles after its sweep has killed whatever still
      // holds the lease, grandchildren included, so a timeout cannot hang.
      child.borrowed.then(settle, (err) => finish(() => reject(err)));
    });
  });
}

// The same shell `spawn(..., { shell: true })` uses, spelled out because a
// borrowed child takes a command and an argument list.
function shellCommand() {
  return process.platform === 'win32' ? (process.env.ComSpec || 'cmd.exe') : '/bin/sh';
}
function shellArgs(command) {
  return process.platform === 'win32' ? ['/d', '/s', '/c', command] : ['-c', command];
}

const FGOS_HINT_RE = /\.fgos\b/;
const MISSING_RE = /ENOENT|no such file|not found/i;

/**
 * tsk-4o9: advisory-only. Returns a hint string when `output` (a failed
 * goal-check's combined stdout+stderr) looks like the verify command
 * depended on `.fgos/`'s presence -- which a detached worktree never has
 * (ADR0020; `bin/fgos.mjs`'s `return` re-verify runs inside one). Returns
 * null otherwise. Never changes pass/fail -- callers append this to an
 * already-failing friction record's own `detail`, nothing more.
 */
export function detachedWorktreeFgosHint(output) {
  if (typeof output !== 'string') return null;
  if (!FGOS_HINT_RE.test(output) || !MISSING_RE.test(output)) return null;
  return "hint: this verify command's output mentions .fgos/ together with a missing-file signal -- a detached worktree (bin/fgos.mjs's return re-verify) never carries .fgos/ (ADR0020); if that is the real cause, redesign this item's verify to check real code/behavior instead of .fgos/ presence.";
}

export function runGoalCheck(item, cwd, timeoutMs) {
  return runCommand(item.verify, cwd, timeoutMs);
}

/**
 * Run the repo-invariant checks in order, stopping at the first failure
 * (docs/history/tsk-516-approve-reverify-scope/CONTEXT.md D3/D4). Resolves
 * the same `{passed, status, timedOut, output}` shape `runCommand` does,
 * plus the `command` that actually failed so a caller can name it instead
 * of reporting an anonymous red.
 *
 * An empty `commands` list passes trivially -- that is the configured-off
 * path (an absent `invariantChecks` section), and it MUST stay behaviorally
 * identical to before this existed, for every repo that never opted in.
 */
export async function runInvariantChecks(commands, cwd, timeoutMs) {
  for (const command of commands) {
    const result = await runCommand(command, cwd, timeoutMs);
    if (!result.passed) return { ...result, command };
  }
  return { passed: true, status: 0, timedOut: false, output: '', command: null };
}

/**
 * Report a failed invariant check through the SAME
 * `{passed, status, timedOut, output}` shape a failed verify already
 * carries, so every downstream branch (the blocked move, the friction row,
 * the outcome, the merge abort, the exit status) keeps working unchanged
 * instead of growing a parallel failure path.
 *
 * The failing command is named in `output`: without it, a person reading a
 * red return or a refused merge cannot tell a repo-invariant failure apart
 * from their own item's verify failing — and that distinction is the whole
 * reason this gate is actionable rather than just another red.
 */
export function invariantFailureAsCheck(invariant) {
  return {
    passed: false,
    status: invariant.status,
    timedOut: invariant.timedOut,
    output: `repo-invariant check failed: ${invariant.command}\n${invariant.output}`,
  };
}
